      const sales=data.sales||[],max=Math.max(1,...sales.map(item=>Number(item.revenue)||0));chart.innerHTML=sales.map(item=>{const revenue=Number(item.revenue)||0,barHeight=Math.max(3,revenue/max*100);const date=new Date(`${item.date}T12:00:00`);return `<div class="admin-chart-column" title="${html(item.date)} · ${money(revenue)}"><span class="admin-chart-value">${revenue?money(revenue):'—'}</span><div class="admin-chart-bar" style="height:${barHeight}%"></div><span class="admin-chart-date">${date.toLocaleDateString('en',{weekday:'short'})}</span></div>`;}).join('')||'<div class="admin-empty">No collected revenue in this period yet.</div>';
