    const syncProductCategoryCounts=()=>{$('[data-product-category-count]').textContent=`${$$('input[name="category_ids"]:checked',form).length} selected`;$$('[data-product-categories] .admin-picker-group').forEach(group=>{const selected=group.querySelectorAll('input:checked').length,total=group.querySelectorAll('input').length;group.querySelector('summary small').textContent=selected?`${selected} selected`:`${total} options`;});};
    const categoryChecks=(selected=[])=>{const selectedIds=new Set(selected.map(Number));const byGroup=new Map();allCategories.forEach(category=>{const key=category.group_name||'Categories';if(!byGroup.has(key))byGroup.set(key,[]);byGroup.get(key).push(category);});$('[data-product-categories]').innerHTML=[...byGroup].map(([groupName,categories])=>{const chosen=categories.filter(category=>selectedIds.has(Number(category.id))).length;return `<details class="admin-picker-group" ${chosen?'open':''}><summary><span>${html(groupName)}</span><small>${chosen?`${chosen} selected`:`${categories.length} options`}</small></summary><div class="admin-picker-options">${categories.map(category=>`<label class="admin-picker-option admin-category-option"><input type="checkbox" name="category_ids" value="${Number(category.id)}" ${selectedIds.has(Number(category.id))?'checked':''}><span>${html(category.name)}</span></label>`).join('')}</div></details>`;}).join('')||'<div class="admin-empty">Create a category to classify your fragrances.</div>';syncProductCategoryCounts();filterProductCategories();};
    const renderProductBrandOptions=()=>{const query=$('[data-product-house-search]').value.trim().toLocaleLowerCase();houseOptions.innerHTML=allBrands.map(brand=>`<label class="admin-picker-option" ${String(brand.name).toLocaleLowerCase().includes(query)?'':'hidden'}><input type="checkbox" value="${Number(brand.id)}" ${Number(brand.id)===Number(brandSelect.value)?'checked':''}><span>${html(brand.name)}</span></label>`).join('');$('[data-product-house-empty]').hidden=allBrands.some(brand=>String(brand.name).toLocaleLowerCase().includes(query));};
