    const filterProductCategories=()=>{const query=$('[data-product-category-search]').value.trim().toLocaleLowerCase();$('[data-product-categories]').querySelectorAll('.admin-picker-group').forEach(group=>{const groupMatches=group.querySelector('summary').textContent.toLocaleLowerCase().includes(query);let visible=0;group.querySelectorAll('.admin-picker-option').forEach(option=>{const match=!query||groupMatches||option.textContent.toLocaleLowerCase().includes(query)||option.querySelector('input').checked;option.hidden=!match;if(match)visible++;});group.hidden=visible===0;if(query&&visible)group.open=true;});};
