    const onVariantAction=event=>{const remove=event.target.closest('[data-remove-variant]');if(remove){const row=remove.closest('[data-variant-id]');if(row.dataset.variantId)pendingVariantDeletes.push(Number(row.dataset.variantId));row.remove();}};
    form.addEventListener('submit',saveProduct);$('[data-add-variant]')?.addEventListener('click',()=>variants.insertAdjacentHTML('beforeend',variantRow()));variants.addEventListener('click',onVariantAction);
