    $('[data-product-brand-toggle]').addEventListener('click',()=>{const panel=$('[data-product-brand-panel]'),open=panel.hidden;panel.hidden=!open;$('[data-product-brand-toggle]').setAttribute('aria-expanded',String(open));if(open)$('[data-product-brand-search]').focus();});
    $('[data-product-brand-search]').addEventListener('input',renderProductBrandFilters);
    brandFilterOptions.addEventListener('change',event=>{const checkbox=event.target.closest('input[type="checkbox"]');if(!checkbox)return;if(checkbox.checked)selectedBrandFilters.add(checkbox.value);else selectedBrandFilters.delete(checkbox.value);renderProductBrandFilters();loadProducts(1);});
    $('[data-clear-product-brands]').addEventListener('click',()=>{selectedBrandFilters.clear();$('[data-product-brand-search]').value='';renderProductBrandFilters();loadProducts(1);});
