    if(!list)return;
    let brands=[],previewProducts=[],page=1;
    const pageSize=12,search=$('[data-brand-search]'),sort=$('[data-brand-sort]'),pagination=$('[data-brand-pagination]'),error=$('[data-brand-error]'),modal=$('[data-brand-modal]'),form=$('[data-brand-form]'),productsModal=$('[data-brand-products-modal]'),productsList=$('[data-brand-products-list]'),productsSearch=$('[data-brand-products-search]');
    const renderPreview=()=>{productsList.innerHTML=renderTaxonomyProductList(previewProducts,productsSearch.value);};bindTaxonomyProductNavigation(productsList);
    const load=async()=>{try{const results=await Promise.all([api('../api/brand.php'),api('../api/admin/taxonomy.php?type=brands')]);const counts=new Map((results[1].data||[]).map(item=>[Number(item.id),item]));brands=(results[0].data||[]).map(item=>({...item,...(counts.get(Number(item.id))||{})}));render();}catch(e){showError(error,e.message);}};
