      pagination.innerHTML='<span>Showing '+(filtered.length?((page-1)*pageSize+1):0)+'–'+Math.min(page*pageSize,filtered.length)+' of '+filtered.length+' houses · Page '+page+' of '+pages+'</span><div><button type="button" data-brand-page="'+Math.max(1,page-1)+'" '+(page<=1?'disabled':'')+'>← Previous</button><button type="button" class="active" aria-current="page">'+page+'</button><button type="button" data-brand-page="'+Math.min(pages,page+1)+'" '+(page>=pages?'disabled':'')+'>Next →</button></div>';
